{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Events & Sessions</title>
  <meta name="description" content="Clinical, sensory sound bath experiences — group events and private sessions in {{CITY}}, {{STATE}}. Book the next restorative gathering.">
  <link rel="icon" href="data:;base64,=" />
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="page-root">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="main-nav" aria-label="Primary">
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button id="nav-toggle" class="nav-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <svg class="hero-pattern" viewBox="0 0 800 200" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#6EE7B7"/><stop offset="1" stop-color="#60A5FA"/></linearGradient></defs><rect width="800" height="200" fill="url(#g1)" opacity="0.12"/></svg>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">A guided sound immersion for clarity and calm</h1>
          <p class="subtitle">Clinical listening, sensory design — group sound baths and bespoke private sessions in {{CITY}}, {{STATE}}. Our practice blends evidence-informed facilitation with tactile, resonant instruments to help you re-center.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="events.html">See upcoming events</a>
            <a class="btn ghost" href="private-sessions.html">Private sessions</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card-inner">
            <p class="muted">Next event</p>
            <h3 class="next">{{NEXT_EVENT_DATE}}</h3>
            <p class="small">Hosted at {{VENUE_NAME}} — facilitated by {{FACILITATOR_NAME}}.</p>
            <a class="btn small" href="book.html">Reserve a spot</a>
          </div>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof wrap">
      <h2 class="section-title">Notes from participants</h2>
      <div class="testimonials" id="testimonials">
        <blockquote class="quote">"A carefully held sound field — I left with a steady pulse and clearer breathing."<cite>— A. Rivera</cite></blockquote>
        <blockquote class="quote">"Precise, peaceful, and unexpectedly playful. The tuning forks were revelatory."<cite>— M. Chen</cite></blockquote>
        <blockquote class="quote">"This is a premium sensory offering. The space felt clinical and warm at once."<cite>— S. Patel</cite></blockquote>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits">
      <div class="wrap">
        <h2 class="section-title">Who benefits</h2>
        <p class="lead">A hybrid model — restorative resonance that pairs measurable relaxation techniques with creative sonic textures.</p>
        <ul class="benefit-grid">
          <li>
            <strong>Stress modulation</strong>
            <p>Guided breathwork plus low-frequency bowls to support the autonomic nervous system.</p>
          </li>
          <li>
            <strong>Improved focus</strong>
            <p>Targeted overtones and sustained harmonics to aid attentional reset.</p>
          </li>
          <li>
            <strong>Deep rest</strong>
            <p>Extended landscape sections designed to facilitate nervous system downshift.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process wrap">
      <h2 class="section-title">Session flow — what to expect</h2>
      <ol class="flow">
        <li>
          <h3>Arrival & settling</h3>
          <p>Quiet entry, orientation, and an intentional 10–15 minute grounding routine with breath cues.</p>
        </li>
        <li>
          <h3>Sonic immersion</h3>
          <p>Instruments used vary by event: crystal bowls, gong, chimes, and a monochord for layered harmonics. Facilitator-led transitions scaffold the experience.</p>
        </li>
        <li>
          <h3>Integration</h3>
          <p>Soft re-orientation and optional journaling time; we close with short spoken reflection and practical aftercare recommendations.</p>
        </li>
      </ol>
      <div class="what-to-bring">
        <h4>What to bring</h4>
        <p>Yoga mat or blanket, an eye-cover, a pillow, and water. Wear layers for temperature comfort.</p>
      </div>
    </section>

    <!-- FAQ (short) -->
    <section class="faq wrap" id="faq">
      <h2 class="section-title">Clinical FAQs</h2>
      <div class="faqs">
        <details>
          <summary>Are there contraindications?</summary>
          <div class="answer">If you are pregnant, have a pacemaker, recent head injury, uncontrolled epilepsy, or severe psychiatric condition, consult your provider before booking. If in doubt, email us at {{EMAIL}}.</div>
        </details>
        <details>
          <summary>How long is a typical group sound bath?</summary>
          <div class="answer">Group sessions usually run 60–75 minutes including arrival and integration time.</div>
        </details>
        <details>
          <summary>Can I fall asleep?</summary>
          <div class="answer">Yes — falling asleep can be a natural part of deep relaxation. We create a safe, low-light environment suitable for restorative rest.</div>
        </details>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet wrap" id="guide">
      <div class="magnet-inner">
        <div>
          <h2 class="section-title">Free preparation guide</h2>
          <p>Get our "Before Your Sound Bath" checklist: practical habits, breathing primers, and contraindication notes to help you prepare.</p>
        </div>
        <form id="magnet-form" class="magnet-form" aria-label="Download guide">
          <label for="email">Email</label>
          <input type="email" id="email" name="email" placeholder="you@domain.com" required>
          <button type="submit" class="btn primary">Send me the guide</button>
          <p class="muted small">We respect your privacy. No spam. You can unsubscribe any time.</p>
        </form>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta">
      <div class="wrap">
        <h2>Ready to book a session?</h2>
        <p class="muted">Group seats and private appointments fill quickly — reserve your time with {{FACILITATOR_NAME}}.</p>
        <div class="cta-row">
          <a class="btn primary large" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact us</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <div class="brand-small">{{BUSINESS_NAME}}</div>
        <address class="muted">{{VENUE_NAME}} • {{CITY}}, {{STATE}}<br>Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
      </div>
      <div class="foot-right">
        <nav aria-label="Footer">
          <a href="events.html">Events</a>
          <a href="private-sessions.html">Private</a>
          <a href="about.html">Our practice</a>
          <a href="terms.html">Terms</a>
        </nav>
      </div>
    </div>
    <svg class="footer-pattern" viewBox="0 0 600 80" preserveAspectRatio="none" aria-hidden="true"><use href="assets/img/pattern.svg#p"/></svg>
  </footer>
</body>
</html>"} 
