{"path":"assets/css/styles.css","content":"/* Core styles — bold_playful + clinical_calm */
:root{
  --bg:#0f172a;--card:#071029;--muted:#9aa7bb;--accent1:#6ee7b7;--accent2:#60a5fa;--glass:rgba(255,255,255,0.06);
  --radius:14px;--max-width:1100px;--wrap-padding:24px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; color:#e6eef6;background:linear-gradient(180deg,var(--bg) 0%, #061028 100%);}
.wrap{max-width:var(--max-width);margin:0 auto;padding:36px var(--wrap-padding)}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(5,10,20,0.6),rgba(2,6,10,0.3));border-bottom:1px solid rgba(255,255,255,0.03)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{font-weight:700;color:var(--accent1);text-decoration:none;font-size:1.1rem}
.nav{margin-left:auto;display:flex;align-items:center;gap:12px}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:10px}
.nav a:hover{color:#fff;background:rgba(255,255,255,0.025)}
.nav .cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#04263a;padding:8px 14px;border-radius:12px;font-weight:700}
.nav-toggle{display:none;background:none;border:0;color:var(--muted);padding:8px}

.hero{padding:56px 0 40px;position:relative;overflow:hidden}
.hero-pattern{position:absolute;left:-6%;top:-4%;width:120%;height:320px;opacity:0.15}
.hero-inner{display:flex;gap:28px;align-items:stretch}
.hero-copy{flex:1;color:#f8fbff}
.title{font-size:2.1rem;margin:0 0 12px;color:#fff}
.subtitle{color:var(--muted);margin:0 0 18px}
.hero-ctas .btn{margin-right:10px}
.hero-card{width:300px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border-radius:18px;padding:18px;box-shadow:0 6px 24px rgba(2,6,12,0.6);border:1px solid rgba(255,255,255,0.03)}
.card-inner .next{margin:.2rem 0;color:#fff}
.btn{display:inline-block;text-decoration:none;padding:10px 16px;border-radius:12px;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#04263a}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}
.btn.small{padding:8px 12px;font-size:0.9rem}
.btn.large{padding:14px 20px;font-size:1rem}

.section-title{color:#e8f9ff;margin:0 0 12px;font-size:1.15rem}
.social-proof{padding-top:18px}
.testimonials{display:flex;gap:14px;overflow:hidden}
.quote{background:var(--glass);padding:18px;border-radius:12px;color:var(--muted);flex:1;border:1px solid rgba(255,255,255,0.03)}
.quote cite{display:block;margin-top:12px;color:#bcd9e8;font-size:.9rem}

.benefits{padding:40px 0}
.benefit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;list-style:none;padding:0;margin:20px 0 0}
.benefit-grid li{background:rgba(255,255,255,0.02);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}

.process{padding:28px 0}
.flow{margin:18px 0 0;padding-left:18px}
.flow li{margin-bottom:12px}
.what-to-bring{margin-top:12px;background:rgba(96,165,250,0.06);padding:12px;border-radius:10px;color:var(--muted)}

.faq details{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;margin-bottom:8px;border:1px solid rgba(255,255,255,0.02)}
.faq summary{cursor:pointer;color:#e6f4ff}
.faq .answer{margin-top:10px;color:var(--muted)}

.lead-magnet{margin:28px 0;padding:20px;background:linear-gradient(180deg,rgba(6,12,22,0.4),rgba(6,12,22,0.3));border-radius:12px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.magnet-form{display:flex;flex-direction:column;gap:10px;min-width:220px}
.magnet-form input{padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eaf7ff}
.magnet-form label{color:var(--muted);font-size:.9rem}
.muted{color:var(--muted)}
.small{font-size:.9rem}

.final-cta{padding:34px 0;background:linear-gradient(90deg,rgba(96,165,250,0.06),rgba(110,231,183,0.04));border-top:1px solid rgba(255,255,255,0.01)}
.cta-row{display:flex;gap:12px;margin-top:12px}

.site-footer{padding:22px 0;border-top:1px solid rgba(255,255,255,0.02);position:relative}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:flex-start}
.brand-small{color:var(--accent2);font-weight:700}
.footer-pattern{position:absolute;right:0;bottom:-4px;width:320px;height:80px;opacity:0.15}

/* Responsive */
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-card{width:100%}
  .nav-toggle{display:block}
  .nav{position:fixed;right:12px;top:64px;background:rgba(2,6,12,0.86);flex-direction:column;padding:12px;border-radius:10px;display:none}
  .nav.open{display:flex}
  .wrap{padding:18px}
  .lead-magnet{flex-direction:column}
}

/* subtle decorative pattern overlay via SVG */
.body-pattern{position:fixed;inset:0;pointer-events:none;opacity:0.06}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Nav toggle
  var toggle=document.getElementById('nav-toggle');
  var nav=document.getElementById('main-nav');
  if(toggle && nav){
    toggle.addEventListener('click',function(){
      var open=nav.classList.toggle('open');
      toggle.setAttribute('aria-expanded',String(open));
    });
  }

  // Simple testimonial carousel
  var tbox=document.getElementById('testimonials');
  if(tbox){
    var idx=0; var items=tbox.querySelectorAll('.quote');
    function show(i){ items.forEach(function(el,ei){ el.style.display=(ei===i)?'block':'none'; }); }
    if(items.length){ show(0); setInterval(function(){ idx=(idx+1)%items.length; show(idx); },4500); }
  }

  // FAQ accordion: allow toggle via details (no polyfill here)

  // Lead magnet form: faux submit
  var form=document.getElementById('magnet-form');
  if(form){
    form.addEventListener('submit',function(e){
      e.preventDefault();
      var email=form.querySelector('input[type="email"]').value;
      if(!email) return alert('Please enter an email');
      // simulate async
      var btn=form.querySelector('button');
      var old=btn.innerText; btn.disabled=true; btn.innerText='Sending…';
      setTimeout(function(){ btn.innerText='Sent ✓'; btn.disabled=false; setTimeout(function(){ btn.innerText=old; form.reset(); },1400); },1200);
    });
  }
})();"} 
